//! JSON-lines bridge. Reference and native-source lookup are independent of the
//! Python experiment harness. No proof is generated by this executable.
use anyhow::{bail, ensure, Result};
use num_rational::BigRational as Q;
use numeric_core::{
    FixedPointFormat, FunctionId, OverflowMode, QuantizationRounding, SigmoidCertificate,
    SigmoidRelationContract,
};
use numeric_reference::evaluate_transcendental;
use serde_json::{json, Value};
use std::io::{self, BufRead, Write};
use std::str::FromStr;

fn respond(v: Value) -> Result<Value> {
    match v["command"].as_str().unwrap_or("") {
        "reference" => {
            let bits = v["bits"].as_u64().unwrap_or(256) as u32;
            ensure!((64..=16384).contains(&bits), "invalid precision");
            let inputs = v["inputs"]
                .as_array()
                .ok_or_else(|| anyhow::anyhow!("inputs missing"))?;
            let rows = inputs
                .iter()
                .map(|x| -> Result<Value> {
                    let x = Q::from_str(
                        x.as_str()
                            .ok_or_else(|| anyhow::anyhow!("rational required"))?,
                    )?;
                    let r = evaluate_transcendental(FunctionId::Sigmoid, &x, bits)?;
                    Ok(json!([
                        r.lower_rational().to_string(),
                        r.upper_rational().to_string()
                    ]))
                })
                .collect::<Result<Vec<_>>>()?;
            Ok(json!(rows))
        }
        "contracts" => {
            let mut rows = vec![];
            for bits in [16, 32, 48, 64] {
                rows.push(numeric_approximations::prepare_sigmoid_contract(
                    FixedPointFormat {
                        integer_bits: 8,
                        fractional_bits: bits,
                        signed: true,
                        rounding: QuantizationRounding::NearestTiesToEven,
                        overflow: OverflowMode::Reject,
                    },
                    8,
                )?);
            }
            Ok(serde_json::to_value(rows)?)
        }
        "check" => {
            let contract: SigmoidRelationContract = serde_json::from_value(v["contract"].clone())?;
            let parse = |value: &Value| -> Result<Q> {
                Ok(Q::from_str(value.as_str().ok_or_else(|| {
                    anyhow::anyhow!("rational string required")
                })?)?)
            };
            let records = v["witnesses"]
                .as_array()
                .ok_or_else(|| anyhow::anyhow!("missing witnesses"))?;
            let inputs = v["inputs"]
                .as_array()
                .ok_or_else(|| anyhow::anyhow!("missing expected inputs"))?
                .iter()
                .map(&parse)
                .collect::<Result<Vec<_>>>()?;
            let certificates = records
                .iter()
                .map(|w| -> Result<_> {
                    Ok(SigmoidCertificate {
                        // Bridge authorizes the supplied contract; the harness separately
                        // compares it to the frozen public profile, never the witness.
                        contract_hash: contract.hash_hex(),
                        canonical_input: parse(&w["input"])?,
                        output: parse(&w["output"])?,
                        claimed_radius: parse(&w["radius"])?,
                        terms: w["terms"]
                            .as_array()
                            .ok_or_else(|| anyhow::anyhow!("missing terms"))?
                            .iter()
                            .map(&parse)
                            .collect::<Result<Vec<_>>>()?,
                    })
                })
                .collect::<Result<Vec<_>>>()?;
            let checked = contract.check_batch(&inputs, &certificates)?;
            Ok(json!(checked
                .iter()
                .map(|(e, _)| [e.lower().to_string(), e.upper().to_string()])
                .collect::<Vec<_>>()))
        }
        _ => bail!("unknown bridge command"),
    }
}
fn main() -> Result<()> {
    let stdin = io::stdin();
    let mut out = io::BufWriter::new(io::stdout().lock());
    for line in stdin.lock().lines() {
        let answer = respond(serde_json::from_str(&line?)?)?;
        serde_json::to_writer(&mut out, &answer)?;
        writeln!(out)?;
        out.flush()?;
    }
    Ok(())
}
